def solution():
    prices = [102, 100, 105, 107, 103]
    volumes = [1500, 1600, 1400, 1300, 1350]
    nvi = 1000.0

    for day in range(1, len(prices)):
        if volumes[day] < volumes[day - 1]:
            price_change = (prices[day] - prices[day - 1]) / prices[day - 1]
            nvi *= 1 + price_change

    return round(nvi, 2)
